def migrate_existing_movements(apps, schema_editor):
    """
    Migrate existing StockMovement records to use the new reason ForeignKey.
    This maps old reason codes to new StockMovementReason objects.
    """
    StockMovement = apps.get_model('inventory', 'StockMovement')
    StockMovementReason = apps.get_model('inventory', 'StockMovementReason')
    
    # Get all reasons
    reasons = {r.code: r for r in StockMovementReason.objects.all()}
    
    # Update each movement
    for movement in StockMovement.objects.all():
        if movement.reason_code and movement.reason_code in reasons:
            movement.reason = reasons[movement.reason_code]
            movement.save(update_fields=['reason'])


